(()=>{
  const C=Cimora,{S,M,E,ui,btn,link,art,badge,money,path}=C;
  const stageNames={story:'故事与章节',boards:'分镜与草图',assets:'资产与约束',comic:'漫画排版',motion:'音画视频',audio:'剪辑与声音',review:'审查与交付'};
  function nodeCard(c,n){return `<article class="cm-job-card"><span class="cm-node-icon ${n.kind}">${M.defs[n.kind]?.[1]||'◇'}</span><div><strong>${E(n.title)}</strong><small>${E(n.provider)} · ${money(n.cost)} 示例 / v${n.version}</small></div>${badge(n.status)}${btn(n.status==='failed'?'重试':'查看','node-detail','cm-icon-button',`data-node="${n.id}" aria-label="查看 ${E(n.title)}"`)}</article>`;}
  function studio(c){
    const e=c.e,type=e.productionType==='episode'?'motion':'comic',stages=['story','boards','assets',...(type!=='motion'?['comic']:[]),...(type!=='comic'?['motion','audio']:[]),'review'];
    if(!stages.includes(e.stage))e.stage='story';
    return `<div class="cm-creation-header"><div>${link('← 项目',`/app/projects/${c.p.id}`,'cm-back')}<h1>${E(c.p.name)} <span>${type==='comic'?'漫画':type==='motion'?'视频':'漫画 + 视频'}</span></h1><p>${E(c.c.title)} <i>·</i> ${e.boards.length} 分格 ${type==='comic'?'':`<i>·</i> ${C.seconds(e)} 秒故事板`}</p></div><div class="cm-creation-actions"><div class="cm-view-switch">${btn('☷ 流程','set-view',e.view==='flow'?'selected':'','data-view="flow"')}${btn('⌘ 无限画布','set-view',e.view==='canvas'?'selected':'','data-view="canvas"')}</div>${btn('▷ 运行制作','run-plan','cm-button primary')}${link('◷ 编排',`/app/runs/${c.p.id}/${c.c.id}`,'cm-button ghost')}</div></div><div class="cm-chapter-strip">${C.scopePicker(c,'cm-editor')}<span>本章预算 ${money(e.spent)} / ${money(e.budget)} ${btn('调整','budget','cm-text-link')}</span></div><nav class="cm-step-nav" aria-label="创作阶段">${stages.map((s,i)=>link(`<b>${String(i+1).padStart(2,'0')}</b>${stageNames[s]}`,path(c,s,e.view),s===e.stage?'active':'')).join('')}</nav>${e.view==='canvas'?C.canvas(c):({story:C.adaptationStory||story,boards:C.adaptationBoards||boards,assets:C.comicAssets||assets,comic:C.comicLayout||comic,motion:C.productionMotion||motion,audio:C.productionAudio||audio,review:type!=='comic'&&C.productionReview||C.comicReview||review}[e.stage])(c)}<div class="cm-project-note"><i></i> 项目与章节独立保存 · 页面展示本机示例，运行不会调用模型或扣费</div>`;
  }
  function story(c){const e=c.e;return `<div class="cm-story-layout"><section class="cm-panel cm-story-editor"><div class="cm-panel-title"><div><span class="cm-kicker">STORY ROOM</span><h2>先把故事，讲给世界听。</h2></div><span class="cm-soft-tag">故事 v${e.graph.nodes.find(n=>n.kind==='story')?.version||1}</span></div><div class="cm-story-tools">${btn('✧ 扩写情节','story-expand','cm-button ghost small')}${btn('✎ 润色对白','story-polish','cm-button ghost small')}${btn('↶ 历史版本','story-history','cm-text-link')}</div><label class="cm-label" for="cm-story-text">本章故事 / 可直接编辑</label><textarea id="cm-story-text" class="cm-script-area" data-cm-input="script">${E(e.scriptDraft??e.script)}</textarea><div class="cm-editor-foot"><small>修改后需确认更新，才会标记下游影响。</small>${btn('保存并确认故事','confirm-script','cm-button primary')}</div></section><aside class="cm-story-aside"><section class="cm-panel"><span class="cm-kicker">CHAPTER PLAN</span><h3>一个世界，慢慢展开。</h3><div class="cm-outline-list">${c.p.chapters.map((ch,i)=>link(`<span>${String(i+1).padStart(2,'0')}</span><div><strong>${E(ch.title)}</strong><small>${E(ch.status)}</small></div>↗`,path({...c,c:ch},'story'),'cm-outline-item '+(ch.id===c.c.id?'active':''))).join('')}</div>${btn('✧ 从故事自动拆章','split-chapters','cm-button ghost full')}${btn('＋ 手动添加章节','add-chapter','cm-text-link')}</section><section class="cm-panel cm-tip-card"><span>✦</span><h3>你决定故事的方向。</h3><p>原文、扩写候选与采用版本分别保留。一次只改你想改的部分。</p>${btn('查看下游关系 →','set-view','cm-text-link','data-view="canvas"')}</section></aside></div>`;}
  function boards(c){const e=c.e;return `<div class="cm-stage-toolbar"><div><h2>让文字，先长成分镜。</h2><p>先确认动作与对白，再出草图。可以随时局部修改。</p></div><div>${btn('＋ 添加分格','add-board','cm-button ghost')}${btn('✧ 批量出草图','run-node','cm-button primary','data-node="sketch"')}</div></div><div class="cm-board-grid">${e.boards.map((b,i)=>`<article class="cm-board"><div class="cm-board-image ${b.approved?'':'is-sketch'}">${art(b.art,b.title)}<span class="cm-panel-number">${String(i+1).padStart(2,'0')}</span><span class="cm-image-badge">${b.approved?'已确认成稿':'草图示意'}</span>${btn('✎ 编辑','edit-board','cm-image-edit',`data-index="${i}"`)}</div><div class="cm-board-copy"><div><h3>${E(b.title)}</h3><small>v${b.version} · ${E(b.shot)}</small></div><p>${E(b.action)}</p><blockquote>${E(b.dialogue)}</blockquote><div class="cm-board-actions">${btn('↑','move-board','cm-icon-button',`data-index="${i}" data-dir="-1" aria-label="上移分格 ${i+1}" ${i===0?'disabled':''}`)}${btn('↓','move-board','cm-icon-button',`data-index="${i}" data-dir="1" aria-label="下移分格 ${i+1}" ${i===e.boards.length-1?'disabled':''}`)}${btn('复制','duplicate-board','cm-text-link',`data-index="${i}"`)}${btn(b.approved?'✓ 已确认':'确认草图','approve-board','cm-text-link',`data-index="${i}"`)}</div></div></article>`).join('')}</div><div class="cm-bottom-cta"><p>图文与阅读顺序一同保存，画布节点位置不改变分格顺序。</p>${link('继续确认资产 →',path(c,'assets'),'cm-button primary')}</div>`;}
  function assets(c){const type=M.output(c.p);return `<div class="cm-stage-toolbar"><div><h2>${type==='comic'?'让每一格，都属于同一个世界。':'为表演，准备更完整的世界。'}</h2><p>${type==='comic'?'角色、场景、服装与道具共享版本约束。静态漫画无需声音资产。':'在视觉参考之外，按镜头需要补齐表情、姿势、图层、声音与动作参考。'}</p></div>${link('管理项目资产 ↗','/app/assets','cm-button ghost')}</div><div class="cm-asset-categories">${['角色','场景','道具','服装','画风',...(type!=='comic'?['声音','表情姿势','分层资料']:[])].map((t,i)=>`<button data-cm="asset-category" data-type="${t}" class="cm-asset-type"><span>${['◎','▧','◇','♧','◒','♫','☺','▱'][i]}</span><strong>${t}</strong><small>${S.state.assets.filter(a=>(!a.projectId||a.projectId===c.p.id)&&a.type===t).length} 项可用</small></button>`).join('')}</div><section class="cm-panel"><div class="cm-panel-title"><h3>本章引用 / 固定版本</h3>${btn('＋ 从素材库引用','pick-asset','cm-button ghost small')}</div><div class="cm-reference-grid">${Object.entries(c.e.bindings).map(([aid,v])=>{const a=S.state.assets.find(a=>a.id===aid);return a?`<article>${art(a.art,a.name)}<div><span>${a.type} · 引用 v${v}</span><strong>${E(a.name)}</strong><small>${a.version===v?'✓ 与当前版本一致':'新版本 v'+a.version+' 可同步'}</small>${btn('查看影响','asset-impact','cm-text-link',`data-id="${a.id}"`)}</div></article>`:'';}).join('')||'<div class="cm-empty-small">本章还没有引用资产。可以从项目库引用，或先生成角色草案。</div>'}</div></section><div class="cm-bottom-cta"><p>新版本需要主动同步，已有分格和动画继续保留。</p>${btn('✧ 生成本章资产草案','seed-assets','cm-button primary')}</div>`;}
  function comic(c){const e=c.e;return `<div class="cm-stage-toolbar"><div><h2>用留白，安排故事的呼吸。</h2><p>阅读顺序、气泡、格间距和发布宽度在这里确认。音频不参与漫画交付。</p></div>${btn('↗ 合成漫画 PNG','comic-export','cm-button primary')}</div><div class="cm-layout-workbench"><aside class="cm-panel cm-layout-list"><h3>阅读顺序</h3>${e.boards.map((b,i)=>btn(`<span>${String(i+1).padStart(2,'0')}</span>${E(b.title)}`,'focus-panel',i===ui.selectedBoard?'selected':'',`data-index="${i}"`)).join('')}<hr><label class="cm-label">格间距 <b id="cm-gap-label">${e.comicGap}px</b><input type="range" min="8" max="64" value="${e.comicGap}" data-cm-input="comic-gap" aria-label="漫画格间距"></label><label class="cm-label">输出宽度<select id="cm-comic-width"><option>1080</option><option>800</option></select></label><p>音效字是画面文字，无需音频。<br>PNG 为当前示例画面真实合成。</p></aside><div class="cm-reading-stage"><div class="cm-long-comic" style="gap:${e.comicGap}px"><header><small>CIMORA ORIGINAL</small><h2>${E(c.p.name)}</h2><p>${E(c.c.title)}</p></header>${e.boards.map((b,i)=>`<figure id="cm-panel-${i}" class="${i===ui.selectedBoard?'selected':''}">${art(b.art,b.title)}<figcaption>${E(b.dialogue)}</figcaption></figure>`).join('')}<footer>TO BE CONTINUED ✦</footer></div></div><aside class="cm-panel cm-layout-inspector"><span class="cm-kicker">PANEL INSPECTOR</span><h3>第 ${ui.selectedBoard+1} 格</h3><p>${E(e.boards[ui.selectedBoard]?.title||'')}</p>${btn('✎ 编辑分格与对白','edit-board','cm-button ghost full',`data-index="${ui.selectedBoard}"`)}${btn('✧ 调用创作工具','context-tool','cm-button ghost full','data-kind="panel"')}<div class="cm-tip-card"><strong>漫画是独立作品。</strong><p>可以直接导出，也可以沿用角色和分格继续制作视频。</p></div>${btn('继续制作视频 →','enable-motion','cm-button primary full')}</aside></div>`;}
  function motion(c){const e=c.e;return `<div class="cm-stage-toolbar"><div><h2>让情绪，开始流动。</h2><p>分格可以对应多个镜头。稳定运镜始终保留，增强候选由你主动采用。</p></div><div>${btn('✧ 生成动态候选','run-node','cm-button primary','data-node="motion"')}${btn('配置镜头映射','shot-mapping','cm-button ghost')}</div></div><div class="cm-motion-layout"><section><div class="cm-shot-grid">${e.boards.map((b,i)=>`<article class="cm-shot ${i===ui.selectedBoard?'selected':''}"><button class="cm-shot-thumb" data-cm="select-shot" data-index="${i}">${art(b.art,b.title)}<span>SHOT ${String(i+1).padStart(2,'0')}</span><b>${b.duration||5}s</b></button><div><h3>${E(b.title)}</h3><p>分格 ${i+1} → 镜头 ${i+1}${b.extraShot?'A / '+(i+1)+'B':''}</p><small>稳定版 v1 · ${b.motion||'缓慢推进'}</small></div></article>`).join('')}</div></section><aside class="cm-panel cm-motion-inspector"><div class="cm-panel-title"><h3>镜头 ${ui.selectedBoard+1}</h3>${badge('done','稳定底稿')}</div><div class="cm-motion-preview ${e.previewPlaying?'playing':''}">${art(e.boards[ui.selectedBoard]?.art||0)}<span>${E(e.boards[ui.selectedBoard]?.dialogue)}</span></div><div class="cm-preview-controls">${btn(e.previewPlaying?'Ⅱ 暂停预览':'▷ 播放示意','toggle-preview','cm-button ghost small')}<small>CSS 运镜 / 非视频文件</small></div><label class="cm-label">运镜方案<select data-cm-change="shot-motion">${['缓慢推进','横向摇移','缓慢拉远','固定镜头'].map(t=>`<option ${(e.boards[ui.selectedBoard]?.motion||'缓慢推进')===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="cm-version-choice"><strong>当前采用：${e.graph.nodes.find(n=>n.kind==='motion')?.useStable?'稳定底稿':e.graph.nodes.find(n=>n.kind==='motion')?.adopted?'增强候选':'稳定底稿'}</strong>${btn('使用稳定底稿','stable-fallback','cm-text-link')}${btn('对比增强候选','node-detail','cm-text-link','data-node="motion"')}</div>${btn('＋ 将此格拆为两个镜头','split-shot','cm-button ghost full')}${btn('编辑镜头参数','shot-edit','cm-button ghost full')}</aside></div>`;}
  function audio(c){const e=c.e;return `<div class="cm-stage-toolbar"><div><h2>画面、声音，在此相遇。</h2><p>声音是视频的制作分支；关闭配音也可以交付无声版本。</p></div>${btn('✧ 生成配音示例','run-node','cm-button primary','data-node="voice"')}</div><div class="cm-audio-layout"><section class="cm-panel"><div class="cm-panel-title"><h3>章节时间线</h3><span>${C.seconds(e)}s · 按镜头顺序播放</span></div><div class="cm-track-ruler">${[0,1,2,3].map(i=>`<span>${C.timecode(C.seconds(e)*i/3)}</span>`).join('')}</div><div class="cm-edit-track"><strong>画面</strong><div>${e.boards.map(b=>`<span>${art(b.art,b.title)}</span>`).join('')}</div></div>${[['对白','dialogue'],['字幕','subtitle'],['环境声','ambience'],['配乐','music']].map(([t,k],i)=>`<div class="cm-edit-track sound"><strong>${t}</strong><div class="cm-waveform wave-${i}">${Array.from({length:30},(_,j)=>`<i style="height:${12+(j*13+i*7)%35}px"></i>`).join('')}</div></div>`).join('')}<input class="cm-seek" type="range" min="0" max="${C.seconds(e)}" value="0" data-cm-input="seek" aria-label="章节剪辑播放位置"><div class="cm-editor-foot"><small id="cm-seek-label">00:00 / ${C.timecode(C.seconds(e))} · 音轨布局示意</small>${btn('▷ 预览当前对白','speak-dialogue','cm-button ghost small')}</div></section><aside class="cm-panel"><h3>声音设置</h3><label class="cm-check"><input type="checkbox" data-cm-change="voice-enabled" ${e.voiceEnabled?'checked':''}>启用角色配音</label><label class="cm-label">音色<select data-cm-change="voice-style"><option>温柔清澈 · 预置声音示意</option><option>平静叙述 · 预置声音示意</option></select></label><label class="cm-label">配乐<select data-cm-change="music-style"><option>雨后的钢琴 · 参数示意</option><option>不使用配乐</option></select></label><p class="cm-help">试听使用浏览器系统语音。波形和音轨为交互示意，未合成真实音频。</p>${link('继续质量审查 →',path(c,'review'),'cm-button primary full')}</aside></div>`;}
  function review(c){const nodes=c.e.graph.nodes.filter(n=>n.version>n.adopted),ready=c.e.reviewApproved;return `<div class="cm-stage-toolbar"><div><h2>最后一步，把故事交给观众。</h2><p>先确认采用版本，再生成交付快照。当前原型可导出 PNG 和工程 JSON。</p></div>${btn('查看生产记录','show-events','cm-button ghost')}</div><div class="cm-review-layout"><section class="cm-panel"><h3>交付前检查</h3><div class="cm-review-lines">${[['分格与对白','确认阅读或播放顺序，以及本章文字。'],['资产与版本','固定本次采用的角色、场景和候选。'],['内容与授权','检查原创素材及发布范围。']].map(([t,d],i)=>`<label><input type="checkbox" data-cm-change="review-check" data-index="${i}" ${c.e.reviewChecks?.[i]?'checked':''}><div><strong>${t}</strong><p>${d}</p></div></label>`).join('')}</div><div class="cm-notice">${nodes.length?`${nodes.length} 个步骤有新候选待采用。采用后才进入交付版本。`:'当前没有待采用的新候选。'}</div>${nodes.map(n=>`<div class="cm-candidate-row"><span>${E(n.title)} · 候选 v${n.version} / 已采用 v${n.adopted}</span>${btn('采用','adopt-node','cm-button ghost small',`data-node="${n.id}"`)}</div>`).join('')}</section><aside class="cm-panel"><span class="cm-kicker">DELIVERY</span><h3>${E(c.p.name)}</h3>${art(6,c.p.name,'cm-delivery-cover')}<p>${E(c.c.title)} · ${c.e.boards.length} 分格</p><div class="cm-delivery-buttons">${btn('导出漫画 PNG','comic-export','cm-button primary full')}${btn('导出工程与版本 JSON','export-project','cm-button ghost full')}${btn('模拟视频交付','deliver-motion','cm-button ghost full',M.output(c.p)==='comic'?'disabled':'')}${btn('发布作品快照','publish-work','cm-button ghost full')}</div><small class="cm-help">MP4 仅演示审批与交付记录，不生成视频。作品仅发布到此浏览器的本机广场。</small></aside></div>`;}
  function project(p){if(!p)return S.empty('没有找到项目','请返回工作空间。');const c=M.activate(p.id,p.chapters[0].id);return `<div class="cm-page-heading"><div><span class="cm-kicker">YOUR ORIGINAL WORLD</span><h1>${E(p.name)}</h1><p>${E(p.desc)}</p></div><div>${btn('＋ 新建章节','add-chapter','cm-button ghost')}${link('继续创作 ↗',path(c,c.e.stage),'cm-button primary')}</div></div><section class="cm-project-overview"><div>${art(p.art,p.name)}</div><article><span class="cm-soft-tag">${M.output(p)==='comic'?'漫画项目':M.output(p)==='motion'?'视频项目':'一体化项目'}</span><h2>一个故事，有许多种可能。</h2><p>${E(p.text?.slice(0,150)||'从一句灵感开始，让角色、分格与镜头在同一个工程里生长。')}</p><div class="cm-overview-stats"><span><b>${p.chapters.length}</b>章节</span><span><b>${p.assetIds?.length||0}</b>项目资产</span><span><b>${c.e.graph.nodes.length}</b>制作步骤</span></div><div class="cm-inline-actions">${link('⌘ 打开无限画布',path(c,c.e.stage,'canvas'),'cm-button ghost')}${link('◷ 任务编排',`/app/runs/${p.id}/${c.c.id}`,'cm-button ghost')}</div></article></section>${C.meta('CHAPTERS','章节工程')}<div class="cm-chapter-cards">${p.chapters.map((ch,i)=>{const e=M.ensure(p,ch),cc={p,c:ch,e};return `<article class="cm-panel"><div class="cm-panel-title"><span class="cm-chapter-index">${String(i+1).padStart(2,'0')}</span>${badge(e.run?.status==='failed'?'failed':'done',ch.status)}</div><h3>${E(ch.title)}</h3><p>${e.boards.length} 分格 · ${Object.keys(e.bindings).length} 项资产 · 已用 ${money(e.spent)}</p><div class="cm-inline-actions">${link('流程 →',path(cc,e.stage,'flow'),'cm-button primary small')}${link('无限画布',path(cc,e.stage,'canvas'),'cm-button ghost small')}</div></article>`;}).join('')}</div>`;}
  C.studio=studio;C.project=project;C.nodeCard=nodeCard;C.stageNames=stageNames;C.comicBoards=boards;C.originalStory=story;C.originalAssets=assets;
})();

